// LoadMemberClose allows an eager lookup of values, cached into the
// loaded structs of the objects. This is for an N-1 relationship.
func (cashRegisterL) LoadMemberClose(ctx context.Context, e boil.ContextExecutor, singular bool, maybeCashRegister any, mods queries.Applicator) error {
	var slice []*CashRegister
	var object *CashRegister

	if singular {
		var ok bool
		object, ok = maybeCashRegister.(*CashRegister)
		if !ok {
			object = new(CashRegister)
			ok = queries.SetFromEmbeddedStruct(&object, &maybeCashRegister)
			if !ok {
				return errors.New(fmt.Sprintf("failed to set %T from embedded struct %T", object, maybeCashRegister))
			}
		}
	} else {
		s, ok := maybeCashRegister.(*[]*CashRegister)
		if ok {
			slice = *s
		} else {
			ok = queries.SetFromEmbeddedStruct(&slice, maybeCashRegister)
			if !ok {
				return errors.New(fmt.Sprintf("failed to set %T from embedded struct %T", slice, maybeCashRegister))
			}
		}
	}

	args := make(map[any]struct{})
	if singular {
		if object.R == nil {
			object.R = &cashRegisterR{}
		}
		if !queries.IsNil(object.MemberCloseID) {
			args[object.MemberCloseID] = struct{}{}
		}

	} else {
		for _, obj := range slice {
			if obj.R == nil {
				obj.R = &cashRegisterR{}
			}

			if !queries.IsNil(obj.MemberCloseID) {
				args[obj.MemberCloseID] = struct{}{}
			}

		}
	}

	if len(args) == 0 {
		return nil
	}

	argsSlice := make([]any, len(args))
	i := 0
	for arg := range args {
		argsSlice[i] = arg
		i++
	}

	query := NewQuery(
		qm.From(`members`),
		qm.WhereIn(`members.id in ?`, argsSlice...),
	)
	if mods != nil {
		mods.Apply(query)
	}

	results, err := query.QueryContext(ctx, e)
	if err != nil {
		return errors.Wrap(err, "failed to eager load Member")
	}

	var resultSlice []*Member
	if err = queries.Bind(results, &resultSlice); err != nil {
		return errors.Wrap(err, "failed to bind eager loaded slice Member")
	}

	if err = results.Close(); err != nil {
		return errors.Wrap(err, "failed to close results of eager load for members")
	}
	if err = results.Err(); err != nil {
		return errors.Wrap(err, "error occurred during iteration of eager loaded relations for members")
	}

	if len(memberAfterSelectHooks) != 0 {
		for _, obj := range resultSlice {
			if err := obj.doAfterSelectHooks(ctx, e); err != nil {
				return err
			}
		}
	}

	if len(resultSlice) == 0 {
		return nil
	}

	if singular {
		foreign := resultSlice[0]
		object.R.MemberClose = foreign
		if foreign.R == nil {
			foreign.R = &memberR{}
		}
		foreign.R.MemberCloseCashRegisters = append(foreign.R.MemberCloseCashRegisters, object)
		return nil
	}

	for _, local := range slice {
		for _, foreign := range resultSlice {
			if queries.Equal(local.MemberCloseID, foreign.ID) {
				local.R.MemberClose = foreign
				if foreign.R == nil {
					foreign.R = &memberR{}
				}
				foreign.R.MemberCloseCashRegisters = append(foreign.R.MemberCloseCashRegisters, local)
				break
			}
		}
	}

	return nil
}

